INSERT INTO public.metric_config (id, metric_code, metric_name, formula, weight, threshold, control_type, is_enabled, updated_by, updated_at, version, grading_thresholds) VALUES ('00000000-0000-0000-0000-000000000401', 'GOOD_VALUE_RATE', '好值率', 'count(pv_quality=Good) / count(*) * 100', 0.00, '{"max": 100, "min": 80, "alert": "warning"}', 'STABLE', true, 'admin', '2026-06-22 07:16:22.696229', 1, NULL);
